import pandas as pd, re, numpy as np

def extract(file):
    df = pd.read_excel(file, header=None)
    # find rows starting with year or quarter entries in col0
    data=[]
    for _,row in df.iterrows():
        v = str(row[0]).strip()
        if re.match(r'^\d{4}\.?$', v):
            year=int(v[:4])
            data.append((year,'annual',row[1]))
        elif re.match(r'^\d{4}:', v):
            year=int(v[:4])
            data.append((year,'quarter',row[1]))
    return data
for f in ['/root/ERP-2025-table10.xls','/root/ERP-2025-table12.xls']:
