import pandas as pd, numpy as np, re
from statsmodels.tsa.filters.hp_filter import hpfilter

def load_series(file):
    df = pd.read_excel(file, header=None)
    annual={}
    quarter_data={}
    for _,row in df.iterrows():
        label=str(row[0]).strip()
        val=row[1]
        if pd.isna(val):
            continue
        m=re.match(r'^(\d{4})\.$', label)
        if m:
            annual[int(m.group(1))]=float(val)
        m=re.match(r'^(\d{4}):\s*([IVX]+)\.?', label)
        if m:
            year=int(m.group(1))
            quarter_data.setdefault(year,[]).append(float(val))
    # build annual 1973-2024
    out={}
    for y in range(1973,2025):
        if y in annual:
            out[y]=annual[y]
        elif y in quarter_data:
            out[y]=np.mean(quarter_data[y])
        else:
            out[y]=np.nan
    return pd.Series(out)

pce=load_series('/root/ERP-2025-table10.xls')
pfi=load_series('/root/ERP-2025-table12.xls')
cpi=pd.read_excel('/root/CPI.xlsx')
cpi=cpi.set_index('Year')['CPI_2024']
real_pce=pce/cpi
real_pfi=pfi/cpi
log_pce=np.log(real_pce)
log_pfi=np.log(real_pfi)
cycle_pce, trend_pce = hpfilter(log_pce, lamb=100)
cycle_pfi, trend_pfi = hpfilter(log_pfi, lamb=100)
cor=np.corrcoef(cycle_pce, cycle_pfi)[0,1]
print('cor',cor)
print('rounded',round(cor,5))
print('n',len(cycle_pce), cycle_pce.index[0], cycle_pce.index[-1])
print(real_pce.tail())
print(real_pfi.tail())
