from statsmodels.tsa.filters.hp_filter import hpfilter

def load_series(file):
    df = pd.read_excel(file, header=None)
    annual={}
    quarter_data={}
    current_year=None
    for _,row in df.iterrows():
        label=str(row[0]).strip()
        val=row[1]
        if pd.isna(val):
            continue
        m=re.match(r'^(\d{4})\.$', label)
        if m:
            annual[int(m.group(1))]=float(val)
            current_year=None
            continue
        m=re.match(r'^(\d{4}):\s*([IVX]+)\.?', label)
        if m:
            current_year=int(m.group(1))
            quarter_data.setdefault(current_year,[]).append(float(val))
            continue
        if current_year is not None and re.match(r'^[IVX]+\.?$', label):
            quarter_data.setdefault(current_year,[]).append(float(val))
    out={}
    for y in range(1973,2025):
        if y in annual:
            out[y]=annual[y]
        elif y in quarter_data:
            out[y]=np.mean(quarter_data[y])
        else:
            out[y]=np.nan
    return pd.Series(out)

for f in ['/root/ERP-2025-table10.xls','/root/ERP-2025-table12.xls']:
    s=load_series(f)
    print(f, s.loc[2021:2024])

